import{_ as t,o as a,c as r,a6 as s}from"./chunks/framework.BHBQfcoO.js";const n="/img/lcards-banner.gif",u=JSON.parse('{"title":"What is LCARdS?","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/what-is-lcards.md","filePath":"getting-started/what-is-lcards.md"}'),o={name:"getting-started/what-is-lcards.md"};function i(c,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<div class="warning custom-block"><p class="custom-block-title">⚠️ Work in Progress</p><p>LCARdS is a <strong>hobby</strong> project, not a fully commissioned Starfleet product; expect the occasional tribble.</p><p>Documentation is under continuous revision - it may not be fully complete and/or accurate to the current build of the project. Please open an issue if you find any issues.</p></div><h1 id="what-is-lcards" tabindex="-1">What is LCARdS? <a class="header-anchor" href="#what-is-lcards" aria-label="Permalink to &quot;What is LCARdS?&quot;">​</a></h1><p><img src="'+n+'" alt="LCARdS Banner"></p><p><strong>Build Star Trek LCARS-style dashboards in Home Assistant</strong> LCARdS brings many LCARS-style controls that can you can use to create interesting and interactive dashboards.</p><p>LCARdS originates from, and supersedes, the <a href="https://github.com/snootched/cb-lcars" target="_blank" rel="noreferrer">CB-LCARS</a> project. It is designed to accompany the <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS theme</a>.</p><h2 id="what-makes-it-different" tabindex="-1">What Makes It Different <a class="header-anchor" href="#what-makes-it-different" aria-label="Permalink to &quot;What Makes It Different&quot;">​</a></h2><p><a href="./../cards/">LCARdS Cards</a> share a common set of core features, allowing for consistent features and interactivity across the system.</p><p><strong>State-aware styling</strong>: cards change colour and style in response to HA entity state, individually or in coordinated groups via the <a href="./../core/rules/">Rules Engine</a>.</p><p><strong>Templates everywhere</strong>: many configuration fields accept entity state, attributes, theme tokens, data source values, JavaScript expressions, or Jinja2. <a href="./../core/templates/">Learn more →</a></p><p><strong>Alert Mode</strong>: respond to alert conditions by shifting the entire dashboard colour palette, play sounds, and activate an overlay card. <a href="./../core/alert-mode.html">Learn more →</a></p><p><strong>Animations</strong>: Anime.js v4 is built in; animate any element in response to interactions or entity state changes. <a href="./../core/animations.html">Learn more →</a></p><p><strong>Data Sources</strong>: subscribe to entities, buffer history, run processing pipelines (moving averages, min/max), and use the results in any card field or chart. <a href="./../core/datasources/">Learn more →</a></p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>→ <strong><a href="./installation.html">Installation</a></strong>: install via HACS in under a minute</p><p>→ <strong><a href="./cb-lcars-migration.html">Coming from CB-LCARS?</a></strong>: feature mapping table</p>',15)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
